package com.smartcampus.attendance;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.security.SecureRandom; import java.sql.Timestamp; import java.time.LocalDateTime; import java.util.*;
@RestController @RequestMapping("/api/staff-auth")
class StaffAuthController {
 private final JdbcTemplate db; private final PasswordEncoder encoder; private final SecureRandom random=new SecureRandom();
 @Value("${app.bootstrap-admin.email:}") private String adminEmail; @Value("${app.bootstrap-admin.password:}") private String adminPassword;
 StaffAuthController(JdbcTemplate db,PasswordEncoder encoder){this.db=db;this.encoder=encoder;}
 @PostMapping("/login") Map<String,Object> login(@RequestBody Map<String,Object> body,HttpServletRequest request){String email=val(body,"email").toLowerCase(Locale.ROOT),password=val(body,"password");if(email.isBlank()||password.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Email and password are required");bootstrapAdmin();List<Map<String,Object>> rows=db.queryForList("SELECT id,full_name,email,password_hash,role,department,status FROM staff_users WHERE LOWER(email)=LOWER(?)",email);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid staff email or password");Map<String,Object> u=rows.get(0);if(!"ACTIVE".equalsIgnoreCase(String.valueOf(u.get("STATUS")))||!encoder.matches(password,String.valueOf(u.get("PASSWORD_HASH"))))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid staff email or password");byte[] b=new byte[32];random.nextBytes(b);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(b);long id=((Number)u.get("ID")).longValue();String role=String.valueOf(u.get("ROLE")).toUpperCase(Locale.ROOT);db.update("INSERT INTO staff_sessions(token_hash,user_id,role,expires_at,revoked) VALUES(?,?,?,?,FALSE)",sha(token),id,role,Timestamp.valueOf(LocalDateTime.now().plusHours(8)));db.update("INSERT INTO audit_logs(action_name,actor,detail) VALUES(?,?,?)","STAFF_LOGIN",email,"role="+role+", ip="+request.getRemoteAddr());return Map.of("token",token,"expiresInSeconds",28800,"role",role,"fullName",String.valueOf(u.get("FULL_NAME")),"email",String.valueOf(u.get("EMAIL")),"message","Login successful");}
 @PostMapping("/logout") Map<String,Object> logout(HttpServletRequest r){String t=bearer(r);if(!t.isBlank())db.update("UPDATE staff_sessions SET revoked=TRUE WHERE token_hash=?",sha(t));return Map.of("message","Signed out successfully");}
 @GetMapping("/me") Map<String,Object> me(HttpServletRequest r){String t=bearer(r);if(t.isBlank())throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Staff login required");List<Map<String,Object>> x=db.queryForList("SELECT su.id,su.full_name fullName,su.email,su.role,su.department,su.status,ss.expires_at expiresAt FROM staff_sessions ss JOIN staff_users su ON su.id=ss.user_id WHERE ss.token_hash=? AND ss.revoked=FALSE",sha(t));if(x.isEmpty())throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Session invalid");return x.get(0);}
 private void bootstrapAdmin(){if(adminEmail==null||adminEmail.isBlank()||adminPassword==null||!adminPassword.matches("^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?=.*[^A-Za-z0-9]).{12,72}$"))return;String configuredEmail=adminEmail.trim().toLowerCase(Locale.ROOT);Integer configuredCount=db.queryForObject("SELECT COUNT(*) FROM staff_users WHERE LOWER(email)=LOWER(?)",Integer.class,configuredEmail);if(configuredCount!=null&&configuredCount>0){db.update("UPDATE staff_users SET password_hash=?,role='ADMIN',status='ACTIVE' WHERE LOWER(email)=LOWER(?)",encoder.encode(adminPassword),configuredEmail);return;}Integer adminCount=db.queryForObject("SELECT COUNT(*) FROM staff_users WHERE role='ADMIN'",Integer.class);if(adminCount!=null&&adminCount>0){db.update("UPDATE staff_users SET email=?,password_hash=?,role='ADMIN',department='Administration',status='ACTIVE' WHERE id=(SELECT MIN(id) FROM staff_users WHERE role='ADMIN')",configuredEmail,encoder.encode(adminPassword));}else{db.update("INSERT INTO staff_users(full_name,email,password_hash,role,department,status) VALUES(?,?,?,'ADMIN','Administration','ACTIVE')","System Administrator",configuredEmail,encoder.encode(adminPassword));}}
 static String bearer(HttpServletRequest r){String h=r.getHeader("Authorization");return h!=null&&h.startsWith("Bearer ")?h.substring(7).trim():"";} static String sha(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private String val(Map<String,Object>b,String k){Object x=b.get(k);return x==null?"":String.valueOf(x).trim();}
}
